pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 timeOffset, uint256 blockNumOffset) public {
        // Bound parameters to reasonable values
        amount = bound(amount, 10 ether, 10 ether); // exactly 10 ether to pass require
        timeOffset = bound(timeOffset, 1, 100);
        blockNumOffset = bound(blockNumOffset, 1, 100);

        vm.assume(timeOffset > 0); // ensure block.timestamp > pastBlockTime

        // Record pastBlockTime before the call
        uint256 before = c.pastBlockTime();

        // Warp to a time > pastBlockTime + something to allow the call
        vm.warp(before + timeOffset);
        vm.roll(block.number + blockNumOffset);

        // Send exactly 10 ether
        vm.deal(address(this), 10 ether);
        (bool success, ) = address(c).call{value: 10 ether}("");

        // Get pastBlockTime after the call
        uint256 after = c.pastBlockTime();

        // The rule: after should be strictly greater than before (reference: block.timestamp + 1, mutant: could be less)
        assertTrue(after > before || !success);
    }
}

