pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 timeShift) public {
        uint256 blockTimestamp = block.timestamp;
        uint256 prevPastBlockTime = c.pastBlockTime();

        // Ensure we can satisfy require(block.timestamp > pastBlockTime)
        vm.assume(blockTimestamp + timeShift > prevPastBlockTime);

        // Advance time so that block.timestamp becomes blockTimestamp + timeShift
        vm.warp(blockTimestamp + timeShift);

        // Call the fallback with exactly 10 ether
        vm.deal(address(c), 10 ether);
        (bool success, ) = address(c).call{value: 10 ether}("");

        if (success) {
            // After success, pastBlockTime must be block.timestamp + 1
            assertTrue(c.pastBlockTime() == block.timestamp + 1, "pastBlockTime should be block.timestamp + 1");
        } else {
            // If it reverts, pastBlockTime must be unchanged
            assertTrue(c.pastBlockTime() == prevPastBlockTime, "pastBlockTime should remain unchanged on revert");
        }
    }
}

