        // Ensure blockNumber1 and blockNumber2 are distinct and in range
        vm.assume(blockNumber1 != blockNumber2);
        vm.assume(blockNumber1 < 2**64 && blockNumber2 < 2**64);
        vm.assume(blockNumber1 % 15 != 0 || blockNumber2 % 15 != 0); // at least one not multiple of 15

        // Simulate two calls at different blocks
        vm.deal(address(c), 10 ether);
        vm.deal(address(this), 20 ether);

        // First call at blockNumber1
        vm.roll(blockNumber1);
        vm.warp(block.timestamp + 1);
        (bool success1,) = address(c).call{value: 10 ether}("");

        // Second call at blockNumber2
        vm.roll(blockNumber2);
        vm.warp(block.timestamp + 1);
        (bool success2,) = address(c).call{value: 10 ether}("");

        // Both calls should succeed (no revert due to timestamp or value)
        assertTrue(success1 && success2);

        // The contract should never transfer all its balance to the caller
        // unless the block number is a multiple of 15
        // Since at least one of blockNumber1, blockNumber2 is not a multiple of 15,
        // after the second call the contract balance should still be 10 ether (since one transfer didn't happen)
        // Actually check: balance should never be 0 after two calls if one block wasn't multiple of 15
        uint256 balanceAfter = address(c).balance;
        // If both blocks were multiples of 15, balance would be 0 after first transfer
        // But we ensured at least one not multiple, so balance should be at least 10 ether
        // (The transfer only happens when block.number % 15 == 0, so if neither is multiple, no transfer, balance = 20 ether)
        // If one is multiple, that transfer sends all balance, then second call adds 10 ether again
        // So balance can be 10 or 20, never 0
        assertTrue(balanceAfter > 0);
    }
}

