        // Constrain blockNumber to be realistic and non-negative
        vm.assume(blockNumber <= type(uint256).max - 15);
        // Also need ensure that after warp, the timestamp condition can be satisfied
        // For the reference, we only care about the transfer condition, not the timestamp
        // So we allow the call to revert due to timestamp or value, that's fine
        // We want to observe a successful call to fallback with msg.value == 10 ether
        vm.deal(address(this), 10 ether);

        // Warp to a time after pastBlockTime
        vm.warp(block.timestamp + 1000);

        // Record balance before call
        uint256 balanceBefore = address(c).balance;

        // Call fallback with 10 ether
        (bool success, bytes memory retData) = address(c).call{value: 10 ether}("");

        // If the call succeeded, then we can check the condition
        if (success) {
            // The transfer only happens if block.number % 15 == 0
            if (block.number % 15 == 0) {
                // Balance should have decreased
                assertTrue(address(c).balance < balanceBefore + 10 ether);
            } else {
                // Balance should not have decreased (only increased by 10 ether)
                assertTrue(address(c).balance == balanceBefore + 10 ether);
            }
        } else {
            // If it reverted, the assertion trivially holds
            assertTrue(true);
        }
    }
}

